    if let Some(profile_id) = profile_id {
        merchant_connector_accounts
            .into_iter()
            .filter(|mca| mca.profile_id.as_ref() == Some(&profile_id))
            .collect::<Vec<_>>()
    } else {
        merchant_connector_accounts
    }
}

